import {escapeHtml as esc} from './core.js';
import {buildExaminationText, selectedItems} from './examination-core.js';
const $=s=>document.querySelector(s);
let data, state={answers:{}}, active='instrucoes';
const sections=[['instrucoes','01','Instruções para o exame'],['oracoes','02','Orações e contrição'],['mandamentos','03','Dez Mandamentos'],['igreja','04','Mandamentos da Igreja'],['capitais','05','Sete Pecados Capitais'],['outros','06','Deveres e misericórdia'],['resumo','07','Meu exame e exportação']];
const matches=g=>active==='mandamentos'?g.id.startsWith('mandamento-'):active==='outros'?['estado','misericordia','espirito','clamam'].includes(g.id):g.id===active;
function source(id){const s=data.sources.find(x=>x.id===id);return s?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>`:'';}
function updateStatus(){const n=selectedItems(data,state.answers).length;$('#exam-count').textContent=n?`${n} ponto${n===1?'':'s'} marcado${n===1?'':'s'} para recordar`:'Sem pontos marcados';}
function field(key,label,placeholder='',value=state[key]||''){return `<label class="exam-field">${esc(label)}<textarea data-field="${key}" maxlength="10000" rows="3" placeholder="${esc(placeholder)}" autocomplete="off" spellcheck="false">${esc(value)}</textarea></label>`;}
function render(){
 $('#exam-nav').innerHTML=sections.map(([id,n,title])=>`<button type="button" data-exam-tab="${id}" aria-pressed="${active===id}"><small>${n}</small> ${esc(title)}</button>`).join('');
 let html='';
 if(active==='instrucoes') html=`<div class="eyebrow">PREPARAR O CORAÇÃO</div><h2>Um exame sincero,<br><em>com serenidade e confiança.</em></h2><p>Este roteiro ajuda a recordar e preparar o que levar ao sacerdote. Não é uma confissão sacramental e não avalia o estado da sua alma.</p>${data.instructions.map(x=>`<article class="exam-instruction"><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p></article>`).join('')}<div class="exam-source">Base: ${source('pio-penitencia')} · ${source('trento')}</div><button class="primary" data-exam-tab="oracoes">Começar pelas orações →</button>`;
 else if(active==='oracoes') html=`<div class="eyebrow">LUZ E ARREPENDIMENTO</div><h2>Orações para<br><em>este recolhimento.</em></h2>${data.prayers.map(p=>`<article class="exam-prayer"><h3>${esc(p.title)}</h3><div class="exam-prayer-columns"><div><small>PORTUGUÊS</small><p>${esc(p.pt).replaceAll('\n','<br>')}</p></div><div lang="la"><small>LATINE</small><p>${esc(p.la).replaceAll('\n','<br>')}</p></div></div><p class="exam-source">${esc(p.note)}<br>${source(p.source)}</p></article>`).join('')}<button class="primary" data-exam-tab="mandamentos">Percorrer os Mandamentos →</button>`;
 else if(active==='resumo') {
  const selected=selectedItems(data,state.answers);
  html=`<div class="eyebrow">A CAMINHO DO SACRAMENTO</div><h2>Meu exame<br><em>de consciência.</em></h2><p>Reveja o que deseja recordar, sem transformar este auxílio em uma contagem de culpa. A mesma falta pode aparecer em vários temas; não precisa ser confessada repetidamente.</p><label class="exam-field">Tempo desde a última confissão<input type="text" data-field="last" maxlength="200" value="${esc(state.last||'')}" placeholder="Opcional; por exemplo: cerca de um mês" autocomplete="off"></label>${selected.length?selected.map(item=>`<article class="exam-summary-item"><small>${esc(item.group)}</small><p>${esc(item.text)}</p>${item.frequency?`<p>Frequência: ${esc(item.frequency)}</p>`:''}${item.note?`<p class="exam-note">${esc(item.note)}</p>`:''}</article>`).join(''):'<p class="exam-empty">Nenhum ponto marcado. Você pode usar apenas as anotações livres abaixo.</p>'}${field('notes','Outras anotações','Escreva com simplicidade; evite nomes de terceiros.')}${field('purpose','Propósito de emenda','Um passo concreto para abandonar o pecado e suas ocasiões.')}${field('repair','Reparação e penitência','Restituição, reparação de danos e, após a confissão, a penitência recebida.')}<div class="exam-export"><h3>Exportar o exame</h3><label class="exam-field">Conteúdo do arquivo<select id="exam-export-scope"><option value="personal">Meu exame — pontos marcados e anotações</option><option value="full">Roteiro completo, orações e minhas anotações</option></select></label><div class="actions"><button class="primary" id="exam-download">Exportar texto (.txt) ↓</button><button class="secondary" id="exam-print">Imprimir / salvar PDF</button></div><p>O arquivo será gerado neste navegador. Para obter PDF, escolha “Salvar como PDF” na janela de impressão. O arquivo exportado contém suas anotações; escolha onde guardá-lo.</p></div><h3>Como proceder e depois da confissão</h3>${data.after.map(t=>`<p>${esc(t)}</p>`).join('')}<details class="exam-sources"><summary>Fontes e critérios desta edição</summary><p>${esc(data.edition)}</p>${data.sources.map(s=>`<p>${source(s.id)}<br>${esc(s.detail)}</p>`).join('')}</details>`;
 } else html=`<div class="eyebrow">PENSAMENTOS · PALAVRAS · OBRAS · OMISSÕES</div><h2>${esc(sections.find(x=>x[0]===active)[2])}</h2><p>Marque somente os pontos que deseja recordar ou esclarecer com o confessor. As perguntas não afirmam que você cometeu um pecado e não determinam sua gravidade.</p>${data.groups.filter(matches).map(g=>`<details class="exam-group" ${active==='mandamentos'?'':'open'}><summary>${esc(g.title)}</summary><div class="exam-group-body"><p>${esc(g.description)}</p>${g.items.map(item=>{const a=state.answers[item.id]||{};return `<div class="exam-question"><label><input type="checkbox" data-answer="${item.id}" ${a.selected?'checked':''}><span>${esc(item.text)}</span></label><div id="answer-${item.id}" class="exam-answer" ${a.selected?'':'hidden'}><label>Número ou frequência aproximada (opcional)<input type="text" data-frequency="${item.id}" maxlength="200" value="${esc(a.frequency||'')}" autocomplete="off" placeholder="Sem inventar uma precisão que não recorda"></label><label>Anotação para recordar (opcional)<textarea rows="2" data-note="${item.id}" maxlength="3000" autocomplete="off" spellcheck="false">${esc(a.note||'')}</textarea></label></div></div>`;}).join('')}<div class="exam-source">${source(g.source)}</div></div></details>`).join('')}<button class="secondary" data-exam-tab="resumo">Rever meu exame e exportar →</button>`;
 $('#exam-content').innerHTML=html; updateStatus();
}
function go(id){active=id;render();$('#exam-content').focus();}
function clear(){state={answers:{}};document.querySelectorAll('.exam-print-frame').forEach(x=>x.remove());$('#exam-clear-confirm')?.remove();render();$('#exam-status').textContent='Anotações e marcações apagadas desta página.';}
function exportText(){return buildExaminationText(data,state,$('#exam-export-scope').value==='full');}
function download(){const blob=new Blob(['\ufeff'+exportText()],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='cathedra-exame-'+new Date().toISOString().slice(0,10)+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#exam-status').textContent='Arquivo gerado. Guarde-o em um local privado.';}
function print(){
 const frame=document.createElement('iframe');frame.className='exam-print-frame';frame.title='Impressão do exame';
 frame.onload=()=>{try{frame.contentWindow.focus();frame.contentWindow.print();$('#exam-status').textContent='Escolha a impressora ou Salvar como PDF na janela de impressão.';}catch{$('#exam-status').textContent='Impressão indisponível. Use Exportar texto.';}};
 frame.srcdoc=`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Exame de consciência</title><style>@page{margin:20mm}body{font:12pt Georgia,serif;color:#222}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;line-height:1.5}</style><body><pre>${esc(exportText())}</pre></body></html>`;
 document.querySelectorAll('.exam-print-frame').forEach(x=>x.remove());document.body.append(frame);
}
async function init(){
 try{const r=await fetch('./examination.json');if(!r.ok)throw Error();data=await r.json();render();
 $('#page-exame').addEventListener('click',e=>{const tab=e.target.closest('[data-exam-tab]');if(tab)go(tab.dataset.examTab);else if(e.target.closest('#exam-download'))download();else if(e.target.closest('#exam-print'))print();else if(e.target.closest('#exam-clear-yes'))clear();else if(e.target.closest('#exam-clear-no')){$('#exam-clear-confirm')?.remove();$('#exam-clear').focus();}else if(e.target.closest('#exam-clear')){if(!$('#exam-clear-confirm')){$('#exam-clear').closest('.page-heading').insertAdjacentHTML('afterend','<div id="exam-clear-confirm" class="exam-privacy" role="group" aria-label="Confirmar limpeza do exame"><p>Apagar as marcações e anotações desta página? Os arquivos já exportados não serão alterados.</p><div class="actions"><button class="secondary" id="exam-clear-no">Manter meu exame</button><button class="primary" id="exam-clear-yes">Apagar as anotações</button></div></div>');$('#exam-clear-no').focus();}}});
 $('#page-exame').addEventListener('input',e=>{const t=e.target;if(t.dataset.field)state[t.dataset.field]=t.value;else if(t.dataset.note||t.dataset.frequency){const id=t.dataset.note||t.dataset.frequency;state.answers[id]||={};state.answers[id][t.dataset.note?'note':'frequency']=t.value;}});
 $('#page-exame').addEventListener('change',e=>{const id=e.target.dataset.answer;if(!id)return;state.answers[id]||={};state.answers[id].selected=e.target.checked;$('#answer-'+id).hidden=!e.target.checked;updateStatus();});
 window.addEventListener('beforeunload',e=>{if(selectedItems(data,state.answers).length||Object.keys(state).some(k=>k!=='answers'&&state[k])){e.preventDefault();e.returnValue='';}});
 $('#gpt-account')?.addEventListener('change',clear);$('#gpt-logout')?.addEventListener('click',clear);
 }catch{$('#exam-content').innerHTML='<h2>Não foi possível abrir o roteiro.</h2><p>Recarregue a página para tentar novamente.</p>';}
}
init();
